-- Immutable, explicit review of every active legacy amendment; never parse free text.
CREATE TABLE loan_billing_legacy_reviews (
 id TEXT PRIMARY KEY, loan_id TEXT NOT NULL REFERENCES loans(id), config_request_key TEXT NOT NULL UNIQUE,
 mappings TEXT NOT NULL CHECK(json_valid(mappings)), reviewed_config TEXT NOT NULL CHECK(json_valid(reviewed_config)), billing_scope_ack INTEGER NOT NULL CHECK(billing_scope_ack=1), opening_ack INTEGER NOT NULL CHECK(opening_ack IN (0,1)), opening_note TEXT, opening_request_key TEXT, opening_reference TEXT, opening_date TEXT, opening_cutoff_rate INTEGER, opening_cutoff_period INTEGER,
 created_by TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','final')),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TRIGGER legacy_review_insert BEFORE INSERT ON loan_billing_legacy_reviews BEGIN
 SELECT CASE WHEN NEW.status<>'pending' OR NEW.billing_scope_ack<>1 OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR EXISTS(SELECT 1 FROM loan_billing_configs WHERE loan_id=NEW.loan_id) OR EXISTS(SELECT 1 FROM loan_billing_config_cancellations WHERE config_request_key=NEW.config_request_key) THEN RAISE(ABORT,'legacy review unauthorized or configuration exists') END;
 SELECT CASE WHEN json_type(NEW.mappings) IS NOT 'array' OR json_array_length(NEW.mappings)=0 OR json_array_length(NEW.mappings)<>(SELECT count(*) FROM loan_term_changes t WHERE t.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id)) THEN RAISE(ABORT,'complete amendment review required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.mappings) x WHERE json_type(x.value) IS NOT 'object' OR json_type(x.value,'$.sourceReason') IS NULL OR json_type(x.value,'$.source') IS NULL OR NOT EXISTS(SELECT 1 FROM loan_term_changes t WHERE t.id=json_extract(x.value,'$.id') AND t.loan_id=NEW.loan_id AND t.effective_date=json_extract(x.value,'$.effectiveDate') AND t.terms=json_extract(x.value,'$.terms') AND t.reason IS json_extract(x.value,'$.sourceReason') AND t.source IS json_extract(x.value,'$.source') AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id))) OR (SELECT count(DISTINCT json_extract(value,'$.id')) FROM json_each(NEW.mappings))<>json_array_length(NEW.mappings) THEN RAISE(ABORT,'legacy source changed or duplicated') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.mappings) x WHERE json_extract(x.value,'$.classification') NOT IN ('rate','none') OR json_extract(x.value,'$.classification') IS NULL OR json_type(x.value,'$.note') IS NOT 'text' OR length(trim(json_extract(x.value,'$.note'))) NOT BETWEEN 1 AND 450 OR (json_extract(x.value,'$.classification')='rate' AND (json_type(x.value,'$.rateBasisPoints') IS NOT 'integer' OR json_extract(x.value,'$.rateBasisPoints') NOT BETWEEN 0 AND 10000 OR json_type(x.value,'$.periodDays') IS NOT 'integer' OR json_extract(x.value,'$.periodDays') NOT IN (30,60,180))) OR (json_extract(x.value,'$.classification')='none' AND (json_type(x.value,'$.rateBasisPoints') IS NOT 'null' OR json_type(x.value,'$.periodDays') IS NOT 'null' OR json_type(x.value,'$.rateId') IS NOT 'null'))) THEN RAISE(ABORT,'explicit complete amendment classification required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.mappings) x JOIN json_each(NEW.mappings) y ON json_extract(x.value,'$.id')<json_extract(y.value,'$.id') WHERE json_extract(x.value,'$.classification')='rate' AND json_extract(y.value,'$.classification')='rate' AND json_extract(x.value,'$.effectiveDate')=json_extract(y.value,'$.effectiveDate')) THEN RAISE(ABORT,'same-day rate amendments require reconciliation') END;
 SELECT CASE WHEN (EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id) AND (NEW.opening_ack<>1 OR NEW.opening_note IS NULL OR length(trim(NEW.opening_note)) NOT BETWEEN 1 AND 450 OR NOT EXISTS(SELECT 1 FROM loan_billing_opening_states s JOIN loan_openings o ON o.loan_id=s.loan_id AND o.journal_id=s.opening_journal_id WHERE s.loan_id=NEW.loan_id AND s.request_key=NEW.opening_request_key AND o.journal_id=NEW.opening_reference AND o.opening_date=NEW.opening_date AND s.cutoff_rate_basis_points=NEW.opening_cutoff_rate AND s.cutoff_period_days=NEW.opening_cutoff_period))) OR (NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id) AND (NEW.opening_ack<>0 OR NEW.opening_note IS NOT NULL OR NEW.opening_request_key IS NOT NULL OR NEW.opening_reference IS NOT NULL OR NEW.opening_date IS NOT NULL OR NEW.opening_cutoff_rate IS NOT NULL OR NEW.opening_cutoff_period IS NOT NULL)) THEN RAISE(ABORT,'reviewed opening cutoff and written reconciliation required') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.mappings) x JOIN loans l ON l.id=NEW.loan_id LEFT JOIN loan_openings o ON o.loan_id=l.id WHERE json_extract(x.value,'$.classification')='rate' AND ((json_extract(x.value,'$.effectiveDate')<=COALESCE(o.opening_date,l.disbursement_date) AND json_type(x.value,'$.rateId') IS NOT 'null') OR (json_extract(x.value,'$.effectiveDate')>COALESCE(o.opening_date,l.disbursement_date) AND (json_type(x.value,'$.rateId') IS NOT 'text' OR length(json_extract(x.value,'$.rateId'))=0)) OR (o.loan_id IS NULL AND json_extract(x.value,'$.effectiveDate')<=l.disbursement_date))) THEN RAISE(ABORT,'legacy rate date cannot be scheduled') END;
END;
CREATE TRIGGER legacy_review_final BEFORE UPDATE ON loan_billing_legacy_reviews BEGIN
 SELECT CASE WHEN OLD.status<>'pending' OR NEW.status<>'final' OR NEW.id IS NOT OLD.id OR NEW.loan_id IS NOT OLD.loan_id OR NEW.config_request_key IS NOT OLD.config_request_key OR NEW.mappings IS NOT OLD.mappings OR NEW.reviewed_config IS NOT OLD.reviewed_config OR NEW.billing_scope_ack IS NOT OLD.billing_scope_ack OR NEW.opening_ack IS NOT OLD.opening_ack OR NEW.opening_note IS NOT OLD.opening_note OR NEW.opening_request_key IS NOT OLD.opening_request_key OR NEW.opening_reference IS NOT OLD.opening_reference OR NEW.opening_date IS NOT OLD.opening_date OR NEW.opening_cutoff_rate IS NOT OLD.opening_cutoff_rate OR NEW.opening_cutoff_period IS NOT OLD.opening_cutoff_period OR NEW.created_by IS NOT OLD.created_by OR NEW.created_at IS NOT OLD.created_at OR NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loan_billing_configs c WHERE c.loan_id=NEW.loan_id AND c.request_key=NEW.config_request_key AND c.created_by=NEW.created_by) THEN RAISE(ABORT,'legacy review cannot be finalized') END;
 SELECT CASE WHEN (EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id) AND (NEW.opening_ack<>1 OR NEW.opening_note IS NULL OR length(trim(NEW.opening_note)) NOT BETWEEN 1 AND 450 OR NOT EXISTS(SELECT 1 FROM loan_billing_opening_states s JOIN loan_openings o ON o.loan_id=s.loan_id AND o.journal_id=s.opening_journal_id WHERE s.loan_id=NEW.loan_id AND s.request_key=NEW.opening_request_key AND o.journal_id=NEW.opening_reference AND o.opening_date=NEW.opening_date AND s.cutoff_rate_basis_points=NEW.opening_cutoff_rate AND s.cutoff_period_days=NEW.opening_cutoff_period))) OR (NOT EXISTS(SELECT 1 FROM loan_openings o WHERE o.loan_id=NEW.loan_id) AND (NEW.opening_ack<>0 OR NEW.opening_note IS NOT NULL OR NEW.opening_request_key IS NOT NULL OR NEW.opening_reference IS NOT NULL OR NEW.opening_date IS NOT NULL OR NEW.opening_cutoff_rate IS NOT NULL OR NEW.opening_cutoff_period IS NOT NULL)) THEN RAISE(ABORT,'reviewed opening cutoff and written reconciliation required') END;
 SELECT CASE WHEN json_array_length(NEW.mappings)<>(SELECT count(*) FROM loan_term_changes t WHERE t.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id)) OR EXISTS(SELECT 1 FROM json_each(NEW.mappings) x WHERE NOT EXISTS(SELECT 1 FROM loan_term_changes t WHERE t.id=json_extract(x.value,'$.id') AND t.loan_id=NEW.loan_id AND t.effective_date=json_extract(x.value,'$.effectiveDate') AND t.terms=json_extract(x.value,'$.terms') AND t.reason IS json_extract(x.value,'$.sourceReason') AND t.source IS json_extract(x.value,'$.source') AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id))) THEN RAISE(ABORT,'legacy source changed during setup') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.mappings) x WHERE json_type(x.value,'$.rateId')='text' AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_changes c WHERE c.id=json_extract(x.value,'$.rateId') AND c.loan_id=NEW.loan_id AND c.config_request_key=NEW.config_request_key AND c.effective_date=json_extract(x.value,'$.effectiveDate') AND c.rate_basis_points=json_extract(x.value,'$.rateBasisPoints') AND c.period_days=json_extract(x.value,'$.periodDays') AND c.reason=json_extract(x.value,'$.note') AND c.created_by=NEW.created_by AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids v WHERE v.change_id=c.id))) THEN RAISE(ABORT,'reviewed rate schedule incomplete') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_rate_changes c WHERE c.loan_id=NEW.loan_id AND c.config_request_key=NEW.config_request_key AND NOT EXISTS(SELECT 1 FROM json_each(NEW.mappings) x WHERE json_type(x.value,'$.rateId')='text' AND json_extract(x.value,'$.rateId')=c.id)) THEN RAISE(ABORT,'unreviewed initial rate change') END;
END;
CREATE TRIGGER legacy_review_no_delete BEFORE DELETE ON loan_billing_legacy_reviews BEGIN SELECT RAISE(ABORT,'legacy review immutable'); END;
DROP TRIGGER billing_config_insert;
CREATE TRIGGER billing_config_insert BEFORE INSERT ON loan_billing_configs BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM loan_billing_config_cancellations WHERE config_request_key=NEW.request_key) THEN RAISE(ABORT,'cancelled configuration key cannot be reused') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') OR NOT EXISTS(SELECT 1 FROM loans l WHERE l.id=NEW.loan_id AND l.principal_minor=NEW.principal_minor AND l.currency=NEW.currency AND l.disbursement_date=NEW.disbursement_date AND l.terms=NEW.reviewed_terms AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id)) OR EXISTS(SELECT 1 FROM loan_repayments r JOIN journal_entries j ON j.source_type='loan-repayment' AND j.source_id=r.id WHERE r.loan_id=NEW.loan_id) OR (EXISTS(SELECT 1 FROM loan_term_changes t WHERE t.loan_id=NEW.loan_id AND NOT EXISTS(SELECT 1 FROM loan_term_change_voids v WHERE v.term_change_id=t.id)) AND NOT EXISTS(SELECT 1 FROM loan_billing_legacy_reviews r WHERE r.loan_id=NEW.loan_id AND r.config_request_key=NEW.request_key AND r.created_by=NEW.created_by AND r.status='pending' AND json_extract(r.reviewed_config,'$.rateBasisPoints')=NEW.rate_basis_points AND json_extract(r.reviewed_config,'$.periodDays')=NEW.period_days AND json_extract(r.reviewed_config,'$.principalMinor')=CAST(NEW.principal_minor AS TEXT) AND json_extract(r.reviewed_config,'$.currency')=NEW.currency AND json_extract(r.reviewed_config,'$.disbursementDate')=NEW.disbursement_date AND json_extract(r.reviewed_config,'$.terms')=NEW.reviewed_terms)) THEN RAISE(ABORT,'billing setup changed, unauthorized, has term amendments, or prior repayment journal exists') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM journal_entries j WHERE j.source_type='loan-disbursement' AND j.source_id=NEW.loan_id AND j.status='posted' AND NOT EXISTS(SELECT 1 FROM journal_entries x WHERE x.reverses_entry_id=j.id AND x.status='posted')) AND NOT EXISTS(SELECT 1 FROM loan_billing_opening_states o JOIN loan_openings l ON l.loan_id=o.loan_id AND l.journal_id=o.opening_journal_id WHERE (l.principal_minor=0 OR EXISTS(SELECT 1 FROM journal_entries j WHERE j.id=l.journal_id AND j.status='posted')) AND o.loan_id=NEW.loan_id AND o.rate_basis_points=NEW.rate_basis_points AND o.period_days=NEW.period_days AND (o.interest_journal_id IS NULL OR EXISTS(SELECT 1 FROM journal_entries k WHERE k.id=o.interest_journal_id AND k.status='posted'))) THEN RAISE(ABORT,'a posted unreversed loan disbursement is required') END;
END;
-- No posting or publication while a reviewed schedule is incomplete or has been corrected.
CREATE TRIGGER legacy_review_event_guard BEFORE INSERT ON loan_billing_events WHEN EXISTS(SELECT 1 FROM loan_billing_legacy_reviews r WHERE r.config_request_key=NEW.config_request_key AND (r.status<>'final' OR EXISTS(SELECT 1 FROM json_each(r.mappings) x WHERE json_type(x.value,'$.rateId')='text' AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_changes c WHERE c.id=json_extract(x.value,'$.rateId') AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids v WHERE v.change_id=c.id))))) BEGIN SELECT RAISE(ABORT,'legacy rate review incomplete or corrected'); END;
CREATE TRIGGER legacy_review_publication_guard BEFORE INSERT ON billing_balance_publications WHEN EXISTS(SELECT 1 FROM loan_billing_configs c JOIN loan_billing_legacy_reviews r ON r.config_request_key=c.request_key WHERE c.loan_id=NEW.loan_id AND (r.status<>'final' OR EXISTS(SELECT 1 FROM json_each(r.mappings) x WHERE json_type(x.value,'$.rateId')='text' AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_changes z WHERE z.id=json_extract(x.value,'$.rateId') AND NOT EXISTS(SELECT 1 FROM loan_billing_rate_change_voids v WHERE v.change_id=z.id))))) BEGIN SELECT RAISE(ABORT,'legacy rate review incomplete or corrected'); END;
